using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CodeForces
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            int step = 0;
            bool Cheak = false;
            if (n >= 1 && n <= Math.Pow(10, 9))
            {
                if (n == 1)
                {
                    Console.WriteLine(n);
                }
                else if (n == 2)
                {
                    Console.WriteLine(1);
                }
                else if (n == 5)
                {
                    Console.WriteLine(3);
                }
                else if (n % 2 == 0)
                {
                    for (;n!= 0 && n != 5;)
                    {
                        if (Cheak == false)
                        {
                            if (n != 0)
                            {
                                n--;
                                step++;
                                Cheak = true;
                            }

                        }
                        if (Cheak == true)
                        {
                            if (n != 0)
                            {
                                n -= 2;
                                step++;
                                Cheak = false;
                            }
                        }
                        if (n == 1)
                        {
                            step++; break;
                        }
                        else if (n == 2)
                        {
                            step++; break;
                        }
                        else if (n == 5)
                        {
                            step += 3; break;
                        }
                    }
                    n = step;
                    Console.WriteLine(n);
                }
                else if (n % 2 != 0 )
                {
                    for (; n != 0 && n != 5; )
                    {
                        if (Cheak == false)
                        {
                            if (n != 0)
                            {
                                n--;
                                step++;
                                Cheak = true;
                            }
                        }
                        if (Cheak == true)
                        {
                            if (n != 0)
                            {
                                n -= 2;
                                step++;
                                Cheak = false;
                            }
                        }
                        if (n == 1)
                        {
                            step++; break;
                        }
                        else if (n == 2)
                        {
                            step++; break;
                        }
                        else if (n == 5)
                        {
                            step+=3; break;
                        }
                    }
                    n = step;
                    Console.WriteLine(n);
                }


            }
        }

    }
}
